"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import gcd

SECONDS_PER_DAY = 86400
MONTHS_PER_GREGORIAN_CYCLE = 4800
LAST_DAY = dt.date.max.toordinal()
UTC = dt.timezone.utc


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: int            # UTC seconds since 0001-01-01T00:00
    end: int


def instant(local, zone):
    # fold=0 uses the earlier instant in a fold and the pre-gap offset in a gap.
    offset = local.replace(tzinfo=zone, fold=0).utcoffset()
    wall = (local.toordinal() - 1) * SECONDS_PER_DAY
    wall += local.hour * 3600 + local.minute * 60 + local.second
    return wall - int(offset.total_seconds())


def timestamp(value, zone):
    days, seconds = divmod(value, SECONDS_PER_DAY)
    if 0 <= days < LAST_DAY:
        utc = dt.datetime.fromordinal(days + 1) + dt.timedelta(seconds=seconds)
        local = utc.replace(tzinfo=UTC).astimezone(zone)
    else:
        # A valid local date at either end of the calendar can cross the UTC year boundary.
        edge = dt.datetime.min if days < 0 else dt.datetime.max.replace(microsecond=0)
        elapsed = value - instant(edge, zone)
        local = (edge + dt.timedelta(seconds=elapsed)).replace(tzinfo=zone)
    # Historical offsets can include seconds. The output format has minute precision.
    return local.isoformat(timespec="seconds")[:25]


def _aligned(anchor, stride, lower):
    """First point on the recurrence grid at or after lower."""
    return lower + (anchor - lower) % stride


def _month_index(day):
    return (day.year - 1) * 12 + day.month - 1


def _candidate_days(rule, first, last):
    first = max(first, rule.start)
    if rule.until is not None:
        last = min(last, rule.until)
    if first > last:
        return

    if rule.unit == "month":
        lower = _aligned(_month_index(rule.start), rule.every, _month_index(first))
        cycle_steps = MONTHS_PER_GREGORIAN_CYCLE // gcd(rule.every, MONTHS_PER_GREGORIAN_CYCLE)
        repeat_at = lower + cycle_steps * rule.every
        for month_index in range(lower, _month_index(last) + 1, rule.every):
            if month_index == repeat_at:
                return  # No selected day exists in any of the repeating active months.
            year, month = divmod(month_index, 12)
            year, month = year + 1, month + 1
            month_len = calendar.monthrange(year, month)[1]
            days = {month_len if item == "last" else item for item in rule.on}
            for number in sorted(days):
                if number <= month_len:
                    repeat_at = None
                    day = dt.date(year, month, number)
                    if first <= day <= last:
                        yield day
        return

    lower, upper = first.toordinal(), last.toordinal()
    anchor = rule.start.toordinal()
    if rule.unit == "day":
        for day in range(_aligned(anchor, rule.every, lower), upper + 1, rule.every):
            yield dt.date.fromordinal(day)
    else:
        monday = anchor - rule.start.weekday()
        stride = 7 * rule.every
        first_week = _aligned(monday, stride, lower - first.weekday())
        for week in range(first_week, upper + 1, stride):
            for weekday in rule.on:
                day = week + weekday
                if lower <= day <= upper:
                    yield dt.date.fromordinal(day)


def candidate_starts(ruledef, first, last):
    """Yield keys and resolved starts in key order, before the times limit."""
    for day in _candidate_days(ruledef.rule, first, last):
        seen = set()
        for time in ruledef.rule.at:
            start = instant(dt.datetime.combine(day, time), ruledef.tz)
            if start not in seen:
                seen.add(start)
                yield f"{day.isoformat()}T{time.isoformat(timespec='minutes')}", start


def expand(ruledef, first, last):
    """Yield the retained candidates whose nominal dates are in [first, last]."""
    rule = ruledef.rule
    if rule.times is None:
        yield from candidate_starts(ruledef, first, last)
        return
    first_date = first.isoformat()
    for count, (key, start) in enumerate(candidate_starts(ruledef, rule.start, last), 1):
        if key[:10] >= first_date:
            yield key, start
        if count == rule.times:
            break
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
import zoneinfo
from dataclasses import dataclass
from functools import lru_cache

from .errors import PlanError, RuleSyntaxError
from .expand import candidate_starts, expand, instant
from .rules import DATE, TIME, Rule, parse_duration, parse_rule

LOCAL_MINUTE = rf"{DATE}T{TIME}"


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: zoneinfo.ZoneInfo
    priority: int


@dataclass
class Override:
    start: int = None        # None for a cancellation
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # rule id -> key -> Override
    min_segment: int


@lru_cache(maxsize=1)
def _iana_names(_search_path):
    # Cache by TZPATH so reset_tzpath() takes effect on the next query.
    return zoneinfo.available_timezones() - {"localtime", "posixrules"}


def _zone(name, label):
    if isinstance(name, str) and name in _iana_names(zoneinfo.TZPATH):
        try:
            return zoneinfo.ZoneInfo(name)
        except (ValueError, zoneinfo.ZoneInfoNotFoundError, OSError):
            pass
    raise PlanError(f"{label}: invalid timezone {name!r}")


def _duration(word, label):
    minutes = parse_duration(word)
    if minutes is None:
        raise PlanError(f"{label}: invalid duration {word!r}")
    return minutes


def _load_rules(raw, default_tz):
    if not isinstance(raw, list):
        raise PlanError("rules must be a list")
    rules = {}
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index}: expected an object")
        rid = item.get("id")
        if not isinstance(rid, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
            raise PlanError(f"rule #{index}: invalid id {rid!r}")
        if rid in rules:
            raise PlanError(f"rule {rid}: duplicate id")
        text = item.get("rule")
        if not isinstance(text, str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        try:
            rule = parse_rule(text)
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, text) from exc
        tz = _zone(item["timezone"], f"rule {rid}") if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError(f"rule {rid}: priority must be an integer")
        rules[rid] = RuleDef(index, rid, rule, tz, priority)
    return rules


def _override_key(ruledef, key):
    if isinstance(key, str):
        if len(ruledef.rule.at) == 1 and re.fullmatch(DATE, key):
            time = ruledef.rule.at[0].isoformat(timespec="minutes")
            key = f"{key}T{time}"
        if re.fullmatch(LOCAL_MINUTE, key):
            try:
                day = dt.date.fromisoformat(key[:10])
            except ValueError:
                pass
            else:
                if any(candidate == key for candidate, _ in candidate_starts(ruledef, day, day)):
                    return key
    raise PlanError(f"rule {ruledef.id}: invalid override key {key!r}")


def _move_start(ruledef, text):
    if isinstance(text, str) and re.fullmatch(LOCAL_MINUTE, text):
        try:
            local = dt.datetime.fromisoformat(text)
        except ValueError:
            pass
        else:
            return instant(local, ruledef.tz)
    raise PlanError(f"rule {ruledef.id}: move override needs a valid 'to'")


def _load_overrides(raw, rules):
    if not isinstance(raw, list):
        raise PlanError("overrides must be a list")
    overrides = {}
    for item in raw:
        if not isinstance(item, dict):
            raise PlanError("override must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str) or rid not in rules:
            raise PlanError(f"override for unknown rule {rid!r}")
        ruledef = rules[rid]
        key = _override_key(ruledef, item.get("key"))
        by_key = overrides.setdefault(rid, {})
        if key in by_key:
            raise PlanError(f"rule {rid}: duplicate override for {key}")
        action = item.get("action")
        if action == "cancel":
            by_key[key] = Override()
        elif action == "move":
            start = _move_start(ruledef, item.get("to"))
            minutes = _duration(item["for"], f"rule {rid}: move override") if "for" in item else None
            by_key[key] = Override(start, minutes)
        else:
            raise PlanError(f"rule {rid}: unknown override action {action!r}")

    for rid, by_key in overrides.items():
        ruledef = rules[rid]
        if ruledef.rule.times is not None:
            pending = set(by_key)
            first = dt.date.fromisoformat(min(pending)[:10])
            last = dt.date.fromisoformat(max(pending)[:10])
            for key, _ in expand(ruledef, first, last):
                pending.discard(key)
                if not pending:
                    break
            if pending:
                raise PlanError(f"rule {rid}: override key {min(pending)} is past the 'times' limit")
    return overrides


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"], "plan")
    rules = _load_rules(raw.get("rules"), default_tz)
    overrides = _load_overrides(raw.get("overrides", []), rules)
    min_segment = _duration(raw["min_segment"], "min_segment") if "min_segment" in raw else 0
    return Plan(list(rules.values()), overrides, min_segment)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import heapq
import re

from .errors import PlanError
from .expand import LAST_DAY, SECONDS_PER_DAY, Occurrence, expand, instant, timestamp
from .plan import LOCAL_MINUTE, load_plan
from .rules import TIME

BOUND = re.compile(rf"{LOCAL_MINUTE}(?::[0-5][0-9])?(?:Z|[+-]{TIME})")


def _parse_bound(text):
    if isinstance(text, str) and BOUND.fullmatch(text):
        try:
            value = dt.datetime.fromisoformat(text[:-1] + "+00:00" if text.endswith("Z") else text)
        except ValueError:
            pass
        else:
            return instant(value, value.tzinfo)
    raise PlanError(f"invalid date-time {text!r}")


def _collect(plan, start, end):
    for ruledef in plan.rules:
        overrides = plan.overrides.get(ruledef.id, {})
        length = ruledef.rule.minutes * 60
        # A nominal local time is less than one day from its UTC instant, even in a gap.
        first = max(1, (start - length - SECONDS_PER_DAY) // SECONDS_PER_DAY + 1)
        last = min(LAST_DAY, (end + SECONDS_PER_DAY) // SECONDS_PER_DAY + 1)
        if first <= last:
            dates = dt.date.fromordinal(first), dt.date.fromordinal(last)
            for key, left in expand(ruledef, *dates):
                right = left + length
                if key not in overrides and left < end and right > start:
                    yield Occurrence(ruledef, key, left, right)
        for key, override in overrides.items():
            left = override.start
            if left is not None:
                right = left + (length if override.minutes is None else override.minutes * 60)
                if left < end and right > start:
                    yield Occurrence(ruledef, key, left, right)


def _query(raw_plan, start, end):
    plan = load_plan(raw_plan)
    lo, hi = _parse_bound(start), _parse_bound(end)
    if lo >= hi:
        raise PlanError("end must be after start")
    return plan, lo, hi


def _as_dict(occ, start, end):
    try:
        left, right = timestamp(start, occ.rule.tz), timestamp(end, occ.rule.tz)
    except (OverflowError, ValueError) as exc:
        raise PlanError(f"rule {occ.rule.id}: timestamp is outside the supported calendar") from exc
    return {"rule": occ.rule.id, "key": occ.key, "start": left, "end": right}


def occurrences(plan, start, end):
    plan, lo, hi = _query(plan, start, end)
    found = sorted(_collect(plan, lo, hi),
                   key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in found]


def _rank(occ):
    return -occ.rule.priority, occ.start, occ.rule.index, occ.key


def _segments(found):
    """Sweep the full intervals and yield each maximal run with the same winner."""
    ordered = sorted(found, key=lambda occ: occ.start)
    edges = sorted({edge for occ in ordered for edge in (occ.start, occ.end)})
    active = []
    next_index = 0
    winner = None
    for edge in edges:
        while next_index < len(ordered) and ordered[next_index].start == edge:
            occ = ordered[next_index]
            heapq.heappush(active, (_rank(occ), occ))
            next_index += 1
        while active and active[0][1].end <= edge:
            heapq.heappop(active)
        next_winner = active[0][1] if active else None
        if next_winner is not winner:
            if winner is not None:
                yield winner, segment_start, edge
            winner, segment_start = next_winner, edge


def agenda(plan, start, end):
    plan, lo, hi = _query(plan, start, end)
    minimum = plan.min_segment * 60
    rows = []
    for occ, left, right in _segments(_collect(plan, lo, hi)):
        if (left != occ.start or right != occ.end) and right - left < minimum:
            continue
        left, right = max(left, lo), min(right, hi)
        if left < right:
            rows.append(_as_dict(occ, left, right))
    return rows

